msg.broker = {};

let mqtt = global.get('mqtt', 'default');
if (typeof mqtt == 'object' && mqtt.enabled == true) {
    if (mqtt.host.length > 0
        && mqtt.port > 0
        && mqtt.topic.length > 0
    ) {
        msg.broker.broker = mqtt.host;
        msg.broker.port = mqtt.port;
        if (mqtt.username.length > 0 && mqtt.password.length > 0) {
            msg.broker.username = mqtt.username;
            msg.broker.password = mqtt.password;
        }

        msg.broker.force = true;
        msg.action = 'connect';
        node.status({fill:"green",shape:"ring",text:"settings ok"});

        return msg;
    } else {
        global.set('mqtt["enabled"]', false, 'default');
        node.status({ fill: "red", shape: "ring", text: "settings ko" });
    }
}

msg.action = 'disconnect';

return msg;

delete msg.filename;

if (typeof msg.payload === 'object') {
    let describe = global.get('describe', 'memoryOnly') || {};
    describe.app = {
        'title': msg.payload.description.slice(5), // remove "DKNR "
        'version' : msg.payload.version,
        'git': msg.payload.name
    };
    global.set('describe', describe, 'memoryOnly');
}
return msg;

if (msg.payload !== '' && typeof global.get('describe.hmi["' + msg.payload + '"]', 'memoryOnly') === 'string') {
    msg.tab = msg.payload;
    msg.name = global.get('describe.hmi["' + msg.payload + '"]', 'memoryOnly');
    msg.payload = 'change';

    return msg;
}

return;

// on unwanted state, stop here
if (msg.payload.match((new RegExp('^(connect|change|lost)$'))) === null) {
    return;
}

// on connect or lost connection, go to auth page
if (msg.payload === 'connect' || msg.payload === 'lost') {
    msg.payload = global.get('describe.app.hmi', 'memoryOnly');;

    return [null, msg];
}

// ui main
msg.version = global.get('describe.app.version', 'memoryOnly');
msg.title = global.get('describe.app.title', 'memoryOnly');
msg.full = msg.title + ' v' + msg.version;
msg.git = "https://github.com/JcDenis/" + global.get('describe.app.git', 'memoryOnly');
msg.lang = 'FR-fr';

// ui menu
msg.menus = {};
msg.titles = {};
msg.payload = {
    'pages': {
        'show': [],
        'hide': []
    }
};
let s =0;
let pages = global.get('describe.hmi', 'memoryOnly') || {};
for (const tab in pages) {
    msg.menus[tab] = true;
    msg.titles[tab] = pages[tab];
    msg.payload.pages.show[s++] = tab;

    if (tab === msg.tab) {
        msg.title = msg.title + ' - ' + pages[tab];
    }
}

return [msg, null];

