if (typeof msg.payload !== 'object' ||
    typeof msg.payload.hmi !== 'object' ||
    typeof msg.payload.project !== 'string'
) {
    return;
}

msg.filename = '/data/projects/' + msg.payload.project + '/package.json'

msg.payload.app = {
    'title': 'DKNR',
    'version' : '0.0',
    'git': ''
}

global.set('describe', msg.payload, 'memoryOnly');

return msg;

msg.payload = global.get('mqtt', 'default') || {}

if (typeof msg.payload.discovery !== 'string' || msg.payload.discorevy == '') {
    msg.payload.discovery = 'homeassistant';
}

return msg;

let units = global.get('units', 'default') || {};
if (typeof units[msg.payload.port] === 'object') {
    msg.payload = 'Ce connecteur est déjà utilisé'
    node.send([null, msg]);
} else if (msg.payload.name !== ' ' && msg.payload.location !== ' ') {
    units[msg.payload.port] = msg.payload;
    global.set('units', units, 'default');
    node.send([msg, null]);
}

return;

let units = global.get('units', 'default') || {};
let size = Object.keys(units).length;
if (size < 2) {
    msg.class = '';
    msg.enabled = true;
    msg.payload = {
        'name': 'Linky_' + size,
        'location': 'Maison',
        'port': size
    }
} else {
    msg.class = 'remove';
    msg.enabled = false;
    msg.payload = {};
}

return msg;

// get descriptions
let describe = global.get('describe', 'memoryOnly');

// Remove dirty code
let lines = msg.payload.toString().replace("\u0002\n","").replace("\r\u0003","");
msg.payload = {};

// Split message by line
lines = lines.split("\r\n");
for (const line in lines) {

	// Prepare checksum
	let i;
	let checksum = 32;
	let myline = lines[line].toString().replace("  "," s").split(" ");

	// Split current message
	let check = myline.pop();
	let origin = myline.pop();
	let label = myline.pop();

	// Regain checksum
	if (check == "s") check = " ";

	// Calcul checksum
	for (i = 0; i < label.length; i++) checksum += label.charCodeAt(i);
	for (i = 0; i < origin.length; i++) checksum += origin.charCodeAt(i);
	checksum = ((checksum%256) & 63) + 32;
	checksum = String.fromCharCode(checksum);

	// Checksum is not ok
	if (checksum != check ) {
		let error = {
			'topic':'',
			'payload': 'Bad Checksum "' + checksum + '" for label "' + label + '".'
		};
		return [null, error];
	}

	// Parse message
	let full = origin;
	let trans = origin;
	let name = label;
	let unit = '';

	// get readbale label
	if (typeof describe.names[label] === 'string') {
		name = describe.names[label];
	}

	// get unit of measurement
	if (typeof describe.units[label] === 'string') {
		unit = describe.units[label];
	}

	// Convert numeric value to number
	if (!isNaN(trans) && isFinite(Number(trans))) trans = Number(trans);

	// set full value with unit
	if (unit !== '') {
		full = trans.toString() + ' ' + unit;
	}

	// OPTARIF : chars, length 4
	if (label == "OPTARIF") {
		if (trans.substring(trans.length - 1) == '.') trans = trans.substring(0, trans.length -1);
		if (trans.substring(trans.length - 1) == '.') trans = trans.substring(0, trans.length -1);

		full = typeof describe.optarif[origin] === 'string' ? describe.optarif[origin] : '';
	}
	// PTEC : chars, length 4
	else if (label == "PTEC") {

		if (trans.substring(trans.length - 1) == '.') trans = trans.substring(0, trans.length -1);
		if (trans.substring(trans.length - 1) == '.') trans = trans.substring(0, trans.length -1);

		full = typeof describe.ptec[origin] === 'string' ? describe.ptec[origin] : '';
	}

	// Add to output
	msg.payload[label] ={
		'raw': origin,
		'value': trans,
		'full': full,
		'name': name,
		'unit': unit
	};
}

// Custom entity
if (typeof msg.payload['HCHC'] === 'object' &&
	typeof msg.payload['HCHP'] === 'object'
) {
	let total = msg.payload['HCHC']['value'] + msg.payload['HCHP']['value'];
	msg.payload['HCHT'] = {
		'raw': total.toString(),
		'value': total,
		'full': total.toString() + ' ' + describe.units['HCHT'],
		'name': describe.names['HCHT'],
		'unit': describe.units['HCHT']
	};
}

// Other info
let unit = global.get('units["' + msg.port + '"]', 'default');
if (typeof unit === 'object') {
	msg.payload['NAME'] = {
		'raw': unit['name'],
		'value': unit['name'],
		'full': unit['name'],
		'name': 'Nom'
	};
	msg.payload['LOCATION'] = {
		'raw': unit['location'],
		'value': unit['location'],
		'full': unit['location'],
		'name': 'Emplacement'
	};
	msg.payload['PORT'] = {
		'raw': unit['port'],
		'value': unit['port'],
		'full': unit['port'],
		'name': 'Port de communication'
	};
}

// Should not happen
if (typeof msg.payload.ADCO !== 'object') {
	let error = {
		'topic': '',
		'payload': 'Uncomplete message received.'
	};
	return [null, error];
}

// Save in memory
let controls = global.get('controls', 'memoryOnly')||{};
controls[msg.port] = msg.payload;
global.set('controls', controls, 'memoryOnly');

// Send to MQTT
return [msg, null];

