    'label':'',
    'value':'',
    'dropdown':'name'
}];

let i = 1;
let units = global.get('units', 'default');
if (typeof units === 'object') {
    for(const port in units) {
        msg.options[i++] = {
            'label': units[port]['name'] + ' - ' + units[port]['location'] + '  - ' + port,
            'value': port,
            'dropdown': 'name'
        }
    }
}

if (i == 1) {
    node.send([null, null]);
}
else if (i == 2) {
    msg.payload = msg.options[1]['value'];
    node.send([msg, null]);
    msg.class = 'remove';
    msg.enlabed = false;
    node.send([null, msg]);
}
else {
    node.send([null, msg]);
}

return;

let enabled = global.get('mqtt.enabled', 'default') || false;
let discovery = global.get('mqtt.discovery', 'default') || '';
let topic = global.get('mqtt.topic', 'default') || '';

if (enabled && discovery.length > 0) {
    let describe = global.get('describe', 'memoryOnly') || {};
    let tics = global.get('controls', 'memoryOnly') || {};
    for (const port in tics) {
        let id = tics[port]['ADCO']['raw'];
        for (const k in describe.discovery_value_template) {
            // !!! limit to sensor for now
            if (describe.type[k] === 'sensor') {
                msg.topic = discovery + '/' + describe.type[k] + '/teleinfo' + '/' + id + '_' + k + '/config';
                msg.payload = {
                    "unique_id": 'teleinfo_ ' + id + '_' + k,
                    "name": describe.names[k],
                    "state_topic": topic + "/" + id,
                    "value_template": describe.discovery_value_template[k],
                    "state_class": describe.discovery_state_class[k],
                    "device_class": describe.discovery_device_class[k],
                    "unit_of_measurement": describe.units[k],
                    "device": {
                        "identifiers": [
                            id
                        ],
                        "manufacturer": "Enedis",
                        "model": "teleinfo_" + id,
                        "name": "Teleinfo " + id
                    }
                };
                node.send(msg);
            }
        }
    }
}

return;
